  "brief": {
    "title": "Frontier AI Models Compared: Intelligence, Speed & Cost",
    "one_liner": "A data-driven comparison of the top 10 frontier AI language models across intelligence, output speed, and pricing based on the Artificial Analysis Intelligence Index v4.0.",
    "goal": "Viewers should quickly understand the trade-offs between intelligence, speed, and cost among leading AI models, enabling informed decisions about which model best fits their use case."
  },
  "sections": [
    {
      "id": "intelligence-ranking",
      "title": "Intelligence Rankings",
      "objective": "Present the Artificial Analysis Intelligence Index scores for the top 10 models, highlighting the leaders and the gap between tiers."
    },
    {
      "id": "speed-comparison",
      "title": "Output Speed Comparison",
      "objective": "Show output tokens per second for each model, revealing that the fastest models are not necessarily the most intelligent."
    },
    {
      "id": "pricing-landscape",
      "title": "Pricing Landscape",
      "objective": "Display the cost per 1M tokens for each model, emphasizing the wide range from $0.30 to $10.00 and the value propositions of budget vs. premium models."
    },
    {
      "id": "tradeoff-analysis",
      "title": "The Intelligence–Speed–Cost Trade-Off",
      "objective": "Synthesize the three dimensions to highlight which models offer the best balance and which excel in a single dimension."
    },
    {
      "id": "methodology-note",
      "title": "About the Index",
      "objective": "Briefly explain the Artificial Analysis Intelligence Index v4.0 methodology and the 10 evaluations it incorporates."
    }
  ],
  "metrics": [
    {
      "id": "top-intelligence",
      "label": "Highest Intelligence Score",
      "value": "57",
      "unit": "AA Index",
      "context": "Gemini 3.1 Pro Preview & GPT-5.4 (xhigh) tied at the top"
    },
    {
      "id": "top-speed",
      "label": "Fastest Output Speed",
      "value": "206",
      "unit": "tokens/sec",
      "context": "gpt-oss-120B (high) leads in raw throughput"
    },
    {
      "id": "lowest-price",
      "label": "Lowest Price",
      "value": "$0.30",
      "unit": "per 1M tokens",
      "context": "gpt-oss-120B (high) and DeepSeek V3.2 tied as cheapest"
    },
    {
      "id": "highest-price",
      "label": "Highest Price",
      "value": "$10.00",
      "unit": "per 1M tokens",
      "context": "Claude Opus 4.6 (max) is the most expensive model evaluated"
    },
    {
      "id": "price-range-factor",
      "label": "Price Range Factor",
      "value": "33×",
      "unit": "",
      "context": "The cheapest model costs 33× less than the most expensive"
    },
    {
      "id": "num-evaluations",
      "label": "Evaluations in Index",
      "value": "10",
      "unit": "benchmarks",
      "context": "Including GDPval-AA, Terminal-Bench Hard, SciCode, GPQA Diamond, and more"
    }
  ]
}

